import argparse, json, os, re, sys, math, random
from pathlib import Path
from typing import Dict, List, Tuple
import numpy as np

_ran_main = False

DATA_DEFAULT = Path('data_fitting/mask_adoption_data')

def load_json_tolerant(path: Path) -> dict:
    text = path.read_text(encoding='utf-8')
    raw = text
    # Strip // and /* */ comments
    text = re.sub(r"/\*.*?\*/", "", text, flags=re.S)
    text = re.sub(r"(^|\s)//.*$", "", text, flags=re.M)
    # Remove trailing commas inside objects/arrays
    text = re.sub(r",\s*([}\]])", r"\1", text)
    try:
        if text != raw:
            print(f"[warn] Sanitized JSON for {path.name}; comments/trailing commas removed")
        return json.loads(text)
    except json.JSONDecodeError as e:
        ctx = raw.splitlines()
        line = max(0, e.lineno - 2)
        snippet = "\n".join(f"{i+1:4d}: {ctx[i]}" for i in range(line, min(line+5, len(ctx))))
        print(f"[error] Failed to parse {path}: {e}\nContext:\n{snippet}")
        raise

class Simulation:
    def __init__(self, attrs: dict, nets: dict, seed: int = 42):
        self.attrs = attrs  # dict[int]->dict
        self.nets = nets    # dict[int]->{'family':..., 'work_school':..., 'community':...}
        self.rng = np.random.RandomState(seed)
        self.params = None
        self.agent_ids = np.array(sorted(attrs.keys()), dtype=int)
        # Precompute adjacency lists per layer
        self.adj = {
            'family': {i: nets.get(i, {}).get('family', []) for i in self.agent_ids},
            'work': {i: nets.get(i, {}).get('work_school', []) for i in self.agent_ids},
            'comm': {i: nets.get(i, {}).get('community', []) for i in self.agent_ids},
        }
        # Precompute bias from risk_perception
        self.bias = np.array([self._bias_for(i) for i in self.agent_ids])

    def _bias_for(self, i: int) -> float:
        a = self.attrs.get(i, {})
        rp = float(a.get('risk_perception', 0.5))
        # Map [0,1] risk to bias roughly in [-1,1]
        return 2.0 * (rp - 0.5)

    @staticmethod
    def sigmoid(x):
        return 1.0 / (1.0 + np.exp(-x))

    def _neighbor_frac(self, state: np.ndarray, layer: str) -> np.ndarray:
        fracs = np.zeros_like(state)
        for idx, i in enumerate(self.agent_ids):
            nbrs = self.adj[layer].get(i, [])
            if not nbrs:
                fracs[idx] = 0.0
            else:
                # Map neighbor ids to positions via binary search
                # Assumes agent_ids is sorted and dense
                pos = np.searchsorted(self.agent_ids, np.array(nbrs, dtype=int))
                pos = pos[(pos >= 0) & (pos < len(self.agent_ids))]
                if len(pos) == 0:
                    fracs[idx] = 0.0
                else:
                    fracs[idx] = float(np.mean(state[pos]))
        return fracs

    def simulate(self, init_state: np.ndarray, days: int, params: Tuple[float, float, float, float, float], start_day: int = 0) -> Tuple[np.ndarray, np.ndarray]:
        w_f, w_w, w_c, inertia, g = params
        N = len(self.agent_ids)
        state = init_state.copy().astype(float)
        daily_rates = np.zeros(days)
        states = np.zeros((days, N))
        for t in range(days):
            fam = self._neighbor_frac(state, 'family')
            work = self._neighbor_frac(state, 'work')
            comm = self._neighbor_frac(state, 'comm')
            gov = g if (start_day + t) >= 10 else 0.0
            logits = self.bias + w_f * fam + w_w * work + w_c * comm + inertia * state + gov
            p = np.clip(self.sigmoid(logits), 1e-6, 1 - 1e-6)
            state = self.rng.binomial(1, p).astype(float)
            states[t] = state
            daily_rates[t] = float(np.mean(state))
        return daily_rates, states

    def fit(self, daily_rates_train: np.ndarray, init_state: np.ndarray) -> Tuple[Tuple[float, float, float, float, float], float]:
        # Small grid for speed
        grid_wf = [0.2, 0.6, 1.0]
        grid_ww = [0.2, 0.6, 1.0]
        grid_wc = [0.1, 0.3, 0.7]
        grid_inertia = [0.3, 0.6, 0.9]
        grid_g = [0.0, 0.5, 1.0]
        best = None
        best_rmse = float('inf')
        for w_f in grid_wf:
            for w_w in grid_ww:
                for w_c in grid_wc:
                    for inertia in grid_inertia:
                        for g in grid_g:
                            pred, _ = self.simulate(init_state, len(daily_rates_train), (w_f, w_w, w_c, inertia, g), start_day=0)
                            rmse = compute_rmse(pred, daily_rates_train)
                            if rmse < best_rmse:
                                best_rmse = rmse
                                best = (w_f, w_w, w_c, inertia, g)
        self.params = best
        return best, best_rmse


def compute_rmse(pred: np.ndarray, actual: np.ndarray) -> float:
    pred = np.asarray(pred, dtype=float)
    actual = np.asarray(actual, dtype=float)
    if np.any(pred < -1e-9) or np.any(pred > 1 + 1e-9) or np.any(actual < -1e-9) or np.any(actual > 1 + 1e-9):
        raise ValueError('Predicted or actual rates out of [0,1] bounds')
    return float(np.sqrt(np.mean((pred - actual) ** 2)))


def load_agent_attributes(path: Path) -> Dict[int, dict]:
    if not path.exists():
        raise FileNotFoundError(f'Missing agent_attributes.csv at {path}')
    # Minimal CSV loader without pandas
    rows = path.read_text(encoding='utf-8').splitlines()
    header = [h.strip() for h in rows[0].split(',')]
    idx_id = header.index('id') if 'id' in header else 0
    attrs = {}
    for r in rows[1:]:
        if not r.strip():
            continue
        parts = [p.strip() for p in r.split(',')]
        try:
            i = int(parts[idx_id])
        except Exception:
            continue
        d = {header[k]: parts[k] for k in range(min(len(header), len(parts)))}
        if 'risk_perception' in d:
            try:
                d['risk_perception'] = float(d['risk_perception'])
            except Exception:
                d['risk_perception'] = 0.5
        else:
            d['risk_perception'] = 0.5
        attrs[i] = d
    return attrs


def load_social_network(path: Path) -> Dict[int, dict]:
    data = load_json_tolerant(path)
    nets = {}
    for k, v in data.items():
        try:
            i = int(k)
        except Exception:
            continue
        fam = list(dict.fromkeys(v.get('family', [])))
        work = list(dict.fromkeys(v.get('work_school', [])))
        comm = list(dict.fromkeys(v.get('community', [])))
        nets[i] = {
            'family': [int(x) for x in fam if x != i],
            'work_school': [int(x) for x in work if x != i],
            'community': [int(x) for x in comm if x != i],
        }
    return nets


def load_train_data(path: Path) -> np.ndarray:
    if not path.exists():
        raise FileNotFoundError(f'Missing train_data.csv at {path}')
    rows = path.read_text(encoding='utf-8').splitlines()
    header = [h.strip() for h in rows[0].split(',')]
    # Try to find a single adoption_rate column
    if 'adoption_rate' in header:
        idx = header.index('adoption_rate')
        vals = []
        for r in rows[1:]:
            if not r.strip():
                continue
            parts = [p.strip() for p in r.split(',')]
            try:
                vals.append(float(parts[idx]))
            except Exception:
                continue
        return np.array(vals, dtype=float)
    else:
        # Fallback: average across agent columns (assumed 0/1) per day
        vals = []
        for r in rows[1:]:
            if not r.strip():
                continue
            parts = [p.strip() for p in r.split(',')]
            try:
                arr = np.array([float(x) for x in parts[1:]], dtype=float)
                vals.append(float(np.mean(arr)))
            except Exception:
                continue
        return np.array(vals, dtype=float)


def synthetic_data(n_agents=200, n_days=40, seed=42):
    rng = np.random.RandomState(seed)
    agent_ids = list(range(n_agents))
    attrs = {i: {'risk_perception': float(rng.rand())} for i in agent_ids}
    nets = {i: {'family': [], 'work_school': [], 'community': []} for i in agent_ids}
    # Simple random graph per layer
    for layer, p in [('family', 0.01), ('work_school', 0.02), ('community', 0.01)]:
        for i in agent_ids:
            for j in range(i+1, n_agents):
                if rng.rand() < p:
                    nets[i][layer].append(j)
                    nets[j][layer].append(i)
    # Create a plausible adoption rate curve for training (monotonic-ish)
    base = np.linspace(0.1, 0.5, 30) + 0.02 * rng.randn(30)
    base = np.clip(base, 0.05, 0.95)
    return attrs, nets, base


def parse_args(argv=None):
    ap = argparse.ArgumentParser()
    ap.add_argument('--data-folder', type=Path, default=DATA_DEFAULT)
    ap.add_argument('--output-folder', type=Path, default=Path('./outputs'))
    ap.add_argument('--seed', type=int, default=42)
    ap.add_argument('--smoke-test', action='store_true')
    ap.add_argument('--no-save', action='store_true')
    ap.add_argument('--use-docker', action='store_true', help='Optional; ignored in default path')
    return ap.parse_args(argv)


def main(argv=None):
    global _ran_main
    if _ran_main:
        print('[info] main() already executed; skipping duplicate run')
        return
    _ran_main = True

    args = parse_args(argv)
    smoke_env = os.getenv('SMOKE_TEST', '0') == '1'
    smoke = args.smoke_test or smoke_env
    rng = np.random.RandomState(args.seed)

    data_folder = args.data_folder
    out_folder = args.output_folder
    out_folder.mkdir(parents=True, exist_ok=True)

    # Load data (with synthetic fallback in smoke-test)
    try:
        attrs = load_agent_attributes(data_folder / 'agent_attributes.csv')
        nets = load_social_network(data_folder / 'social_network.json')
        rates = load_train_data(data_folder / 'train_data.csv')
    except Exception as e:
        if smoke:
            print(f"[warn] Data load failed ({e}); using synthetic data for smoke-test")
            attrs, nets, rates = synthetic_data(seed=args.seed)
        else:
            raise

    if len(rates) < 40:
        raise ValueError('train_data.csv must contain at least 40 days (0–39) to train and forecast')

    # Subsample for smoke-test
    if smoke:
        keep = sorted(list(attrs.keys()))[:min(200, len(attrs))]
        attrs = {i: attrs[i] for i in keep}
        nets = {i: nets.get(i, {'family': [], 'work_school': [], 'community': []}) for i in keep}

    sim = Simulation(attrs, nets, seed=args.seed)

    # Initialize day 0 state from day 0 rate
    init_rate = float(rates[0])
    N = len(sim.agent_ids)
    init_state = (rng.rand(N) < init_rate).astype(float)

    # Train on days 0–29
    train_rates = rates[:30]
    best_params, train_rmse = sim.fit(train_rates, init_state)

    # Forecast days 30–39
    # First roll forward to day 30 using best params to get consistent state
    _, states_hist = sim.simulate(init_state, 30, best_params, start_day=0)
    state_d30 = states_hist[-1]
    pred_rates, _ = sim.simulate(state_d30, 10, best_params, start_day=30)

    # Evaluate RMSE if actual available for days 30–39
    actual_forecast = rates[30:40]
    rmse = compute_rmse(pred_rates, actual_forecast)

    print(f"[info] Trained params: {best_params}; train RMSE: {train_rmse:.4f}; forecast RMSE: {rmse:.4f}")

    if not args.no_save:
        (out_folder / 'predictions.csv').write_text(
            'day,predicted_adoption_rate\n' + "\n".join(f"{30+i},{pred_rates[i]:.6f}" for i in range(10)),
            encoding='utf-8'
        )
        metrics = {
            'RMSE': rmse,
            'train_RMSE': train_rmse,
            'params': {
                'w_family': best_params[0],
                'w_work': best_params[1],
                'w_comm': best_params[2],
                'inertia': best_params[3],
                'gov_effect': best_params[4]
            }
        }
        (out_folder / 'metrics.json').write_text(json.dumps(metrics, indent=2), encoding='utf-8')

    print('[done] Simulation completed successfully')

# Execute main for both direct execution and sandbox wrapper invocation
main()

